# Not autogenerated.
"""Benchmarks for Python book access and ITCH replay."""
# pyright: reportMissingTypeStubs=false, reportUnknownMemberType=false
# pyright: reportUnusedCallResult=false

import importlib.util
import os
from argparse import SUPPRESS
from collections.abc import Iterable
from contextlib import nullcontext
from dataclasses import dataclass
from functools import partial
from pathlib import Path
from tempfile import TemporaryDirectory
from time import perf_counter
from types import ModuleType
from typing import Protocol, cast

import pyperf

from lobo import Book
from lobo.replay import ReplayContext
from lobo.replay.adapters import itch
from lobo.replay.adapters import models as lm
from lobo.sinks import FeatherSink


DEFAULT_ITCH_PATH = Path("data/NASDAQ/01302020.NASDAQ_ITCH50")


class _BenchmarkArgs(Protocol):
    itch_path: str
    scenario: str
    batch_size: int
    buffer_size: int
    feather_directory: str | None


def add_runner_args(command: list[str], args: _BenchmarkArgs) -> None:
    """Forward benchmark inputs to every pyperf worker process."""
    command.extend(
        (
            "--itch-path",
            args.itch_path,
            "--scenario",
            args.scenario,
            "--batch-size",
            str(args.batch_size),
            "--buffer-size",
            str(args.buffer_size),
        )
    )
    if args.feather_directory is not None:
        command.extend(("--feather-directory", args.feather_directory))


def load_custom_example() -> ModuleType:
    """Load the Python ITCH declaration used for the comparison."""
    path = Path(__file__).resolve().parents[2] / "python/examples/itch/adapter.py"
    spec = importlib.util.spec_from_file_location("custom_itch", path)
    if spec is None or spec.loader is None:
        raise ImportError(f"Cannot load adapter definition from {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def time_custom_replay(
    loops: int,
    definition: ModuleType,
    path: str,
    scope: list[str] | None,
    *,
    concurrent: bool,
) -> float:
    """Replay with the ITCH definition from the Python example."""

    elapsed = 0.0
    for _ in range(loops):
        # Directory discovery is outside timing, as for ItchSource.all_available.
        adapter = definition.build_adapter(lm.Source.file(path), scope=scope)
        start = perf_counter()
        with adapter:
            books = adapter.run(concurrent=concurrent)
            count = len(books)
        del books
        seconds = perf_counter() - start
        elapsed += seconds
        print(f"Custom replay: {count:,} books | {seconds:.3f} sec", flush=True)
        if scope is None and concurrent and seconds > 100:
            raise RuntimeError(
                f"Full-file replay exceeded the 100-second limit: {seconds:.3f}s"
            )
    return elapsed


def replay_without_stats(
    source: itch.ItchSource | Iterable[itch.ItchSource], *, concurrent: bool = True
) -> int:
    """Replay one source without statistics and expose the resulting book count."""
    with ReplayContext(
        source=source, collect_stats=False, concurrent=concurrent, cutoff_time=None
    ) as books:
        return len(books)


@dataclass(frozen=True)
class FeatherResult:
    """Output measured after finalization, before deleting the temporary file."""

    rows: int
    file_bytes: int
    batches: int
    replay_seconds: float
    drain_seconds: float


def replay_to_feather(
    source: itch.ItchSource | Iterable[itch.ItchSource],
    batch_size: int,
    buffer_size: int,
    *,
    concurrent: bool = True,
    output_directory: str | None = None,
) -> FeatherResult:
    """Replay to EOF, drain/finalize the sink, and delete its temporary output."""
    with TemporaryDirectory(
        prefix="lobo-feather-bench-", dir=output_directory
    ) as directory:
        path = Path(directory) / "updates.feather"
        sink = FeatherSink(path, batch_size=batch_size, buffer_size=buffer_size)
        replay_start = perf_counter()
        with ReplayContext(
            source=source,
            collect_stats=False,
            concurrent=concurrent,
            cutoff_time=None,
            sinks=[sink],
        ):
            replay_end = perf_counter()
        drain_end = perf_counter()
        # Context exit joins the writer and closes the file before cleanup.
        if not sink.finished or sink.rows_written == 0:
            raise RuntimeError("Feather benchmark did not write and finalize updates")
        return FeatherResult(
            rows=sink.rows_written,
            file_bytes=path.stat().st_size,
            batches=sink.batches_written,
            replay_seconds=replay_end - replay_start,
            drain_seconds=drain_end - replay_end,
        )


def time_replay_to_feather(
    loops: int,
    source: itch.ItchSource | Iterable[itch.ItchSource],
    batch_size: int,
    buffer_size: int,
    *,
    concurrent: bool,
    output_directory: str | None = None,
) -> float:
    """Time the full lifecycle; print output statistics outside the measurement."""
    elapsed = replay_seconds = drain_seconds = 0.0
    result = None
    for _ in range(loops):
        start = perf_counter()
        result = replay_to_feather(
            source,
            batch_size,
            buffer_size,
            concurrent=concurrent,
            output_directory=output_directory,
        )
        elapsed += perf_counter() - start
        replay_seconds += result.replay_seconds
        drain_seconds += result.drain_seconds
    if result is None:
        raise ValueError("benchmark loops must be positive")
    print(
        f"Feather output per replay: {result.rows:,} rows | "
        + f"{result.file_bytes:,} bytes ({result.file_bytes / 1024**3:.3f} GiB) | "
        + f"{result.batches:,} batches | file deleted",
        flush=True,
    )
    print(
        f"Mean time per replay: setup/replay {replay_seconds / loops:.3f} sec | "
        + f"drain/finalize after replay {drain_seconds / loops:.3f} sec",
        flush=True,
    )
    return elapsed


def main() -> None:
    """Run Python API microbenchmarks and full-feed replay benchmarks."""
    default_path = Path(os.environ.get("LOBO_ITCH_PATH", DEFAULT_ITCH_PATH)).resolve()
    runner = pyperf.Runner(add_cmdline_args=add_runner_args)
    runner.argparser.add_argument("--itch-path", default=str(default_path))
    scenarios = (
        "all",
        "micro",
        "replay",
        "aapl",
        "all-tickers",
        "feather",
        "feather-aapl",
        "custom-aapl",
        "custom-all-tickers",
    )
    runner.argparser.add_argument(
        "--scenario",
        choices=scenarios
        + tuple(
            f"{scenario}-single-threaded"
            for scenario in scenarios
            if scenario != "micro"
        ),
        default="all",
        help="benchmark group to run (default: all)",
    )
    runner.argparser.add_argument("--batch-size", type=int, default=8192)
    runner.argparser.add_argument("--buffer-size", type=int, default=262144)
    runner.argparser.add_argument(
        "--feather-directory",
        help=SUPPRESS,
    )
    args = cast(_BenchmarkArgs, runner.parse_args())
    if min(args.batch_size, args.buffer_size) <= 0:
        runner.argparser.error("Feather batch size and buffer size must be positive")

    # The manager owns this directory and forwards it to workers. A killed
    # worker cannot run its finally blocks; manager exit still removes its files.
    directory = (
        TemporaryDirectory(prefix="lobo-feather-run-")
        if args.feather_directory is None
        else nullcontext(args.feather_directory)
    )
    with directory as output_directory:
        args.feather_directory = output_directory
        run_benchmarks(runner, args)


def run_benchmarks(runner: pyperf.Runner, args: _BenchmarkArgs) -> None:
    """Route each named scenario directly to ReplayContext.concurrent."""
    concurrent = not args.scenario.endswith("-single-threaded")
    scenario = args.scenario.removesuffix("-single-threaded")
    if scenario in {"all", "micro"}:
        book = Book()

        runner.bench_func(
            "book.best_bid",
            lambda: book.best_bid,
        )

        runner.bench_func(
            "book.orders.bids.visible_quantity",
            lambda: book.orders.bids.visible_quantity,
        )

        bids = book.orders.bids

        runner.bench_func(
            "bids.visible_quantity",
            lambda: bids.visible_quantity,
        )

    if scenario == "micro":
        return

    itch_path = Path(args.itch_path)
    if not itch_path.is_file():
        message = f"ITCH data missing at {itch_path}; set LOBO_ITCH_PATH"
        raise FileNotFoundError(message)

    runner.metadata["itch_path"] = str(itch_path)
    runner.metadata["replay_mode"] = (
        "multithreaded" if concurrent else "single-threaded"
    )
    mode_suffix = "" if concurrent else ".single_threaded"
    if scenario.startswith("custom-"):
        definition = load_custom_example()
        scope = ["AAPL"] if scenario == "custom-aapl" else None
        name = "aapl" if scope else "all_tickers"
        # Match the reference name so pyperf can directly compare JSON artifacts.
        runner.bench_time_func(
            f"replay.context.{name}{mode_suffix}",
            partial(time_custom_replay, concurrent=concurrent),
            definition,
            str(itch_path),
            scope,
        )
        return
    for feather_scenario, scope in (
        ("feather", "all_tickers"),
        ("feather-aapl", "aapl"),
    ):
        if scenario not in {"all", feather_scenario}:
            continue
        source = (
            itch.ItchSource.all_available(str(itch_path))
            if scope == "all_tickers"
            else itch.ItchSource(str(itch_path), "AAPL")
        )
        runner.bench_time_func(
            f"replay.context.{scope}.feather{mode_suffix}",
            partial(
                time_replay_to_feather,
                concurrent=concurrent,
                output_directory=args.feather_directory,
            ),
            source,
            args.batch_size,
            args.buffer_size,
            metadata={
                "feather_batch_size": args.batch_size,
                "feather_buffer_size": args.buffer_size,
            },
        )
    if scenario in {"all", "replay", "aapl"}:
        runner.bench_func(
            f"replay.context.aapl{mode_suffix}",
            partial(replay_without_stats, concurrent=concurrent),
            itch.ItchSource(str(itch_path), "AAPL"),
        )

    if scenario in {"all", "replay", "all-tickers"}:
        runner.bench_func(
            f"replay.context.all_tickers{mode_suffix}",
            partial(replay_without_stats, concurrent=concurrent),
            itch.ItchSource.all_available(str(itch_path)),
        )


if __name__ == "__main__":
    main()
